describe("validateHevyApiKeyResilient", () => {
	const createValidationClient = () => ({}) as HevyClient;

	function rejectingValidator(status: number, count: number): HevyKeyValidator {
		let calls = 0;
		return vi.fn<HevyKeyValidator>(() => {
			calls += 1;
			if (calls <= count) {
				return Promise.reject(
					new HevyHttpError(`HTTP ${status}`, {
						status,
						method: "GET",
						endpoint: "/v1/user/info",
					}),
				);
			}
			return Promise.resolve("valid");
		});
	}

	it("skips validate entirely on a cache hit", async () => {
		const env = {};
		await cacheValidation("resilient-cached-key", env);
		const validate: HevyKeyValidator = vi.fn();

		const result = await validateHevyApiKeyResilient(
			"resilient-cached-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
		);

		expect(result).toBe("valid");
		expect(validate).not.toHaveBeenCalled();
	});

	it("validates and caches on a miss", async () => {
		const env = {};
		const validate: HevyKeyValidator = vi.fn().mockResolvedValue("valid");

		const result = await validateHevyApiKeyResilient(
			"resilient-fresh-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
		);

		expect(result).toBe("valid");
		expect(validate).toHaveBeenCalledTimes(1);
		await expect(hasCachedValidation("resilient-fresh-key", env)).resolves.toBe(
			true,
		);
	});

	it("never caches an invalid verdict", async () => {
		const env = {};
		const validate: HevyKeyValidator = vi.fn().mockResolvedValue("invalid");

		const result = await validateHevyApiKeyResilient(
			"resilient-invalid-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
		);

		expect(result).toBe("invalid");
		await expect(
			hasCachedValidation("resilient-invalid-key", env),
		).resolves.toBe(false);
	});

	it("retries a transient (non-429) failure and returns the eventual success", async () => {
		const env = {};
		const validate = rejectingValidator(503, 1);

		const result = await validateHevyApiKeyResilient(
			"resilient-retry-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
		);

		expect(result).toBe("valid");
		expect(validate).toHaveBeenCalledTimes(2);
	});

	it("never retries a 429", async () => {
		const env = {};
		const error = new HevyHttpError("HTTP 429", {
			status: 429,
			method: "GET",
			endpoint: "/v1/user/info",
		});
		const validate: HevyKeyValidator = vi.fn().mockRejectedValue(error);

		await expect(
			validateHevyApiKeyResilient(
				"resilient-429-key",
				"https://api.hevyapp.com",
				createValidationClient,
				validate,
				env,
			),
		).rejects.toBe(error);
		expect(validate).toHaveBeenCalledTimes(1);
	});

	it("stops retrying when aborted during backoff, without another attempt", async () => {
		const env = {};
		const controller = new AbortController();
		const validate = rejectingValidator(503, 1);

		const pending = validateHevyApiKeyResilient(
			"resilient-abort-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
			{ signal: controller.signal },
		);
		// Abort while the wrapper is sleeping between attempt 1 and attempt 2.
		setTimeout(() => controller.abort(), 10);

		await expect(pending).rejects.toBeInstanceOf(HevyHttpError);
		expect(validate).toHaveBeenCalledTimes(1);
	});

	it("defers the cache write via waitUntil when given an execution context", async () => {
		const env = {};
		const validate: HevyKeyValidator = vi.fn().mockResolvedValue("valid");
		const waitUntil = vi.fn();

		const result = await validateHevyApiKeyResilient(
			"resilient-deferred-key",
			"https://api.hevyapp.com",
			createValidationClient,
			validate,
			env,
			undefined,
			{ waitUntil },
		);

		expect(result).toBe("valid");
		expect(waitUntil).toHaveBeenCalledTimes(1);
	});
});

import { Duration, Effect, Fiber, Schedule } from "effect";
import { TestClock } from "effect/testing";
import { describe, expect, it } from "vitest";

import { createRetrySchedule } from "./retry-schedule.js";

describe("createRetrySchedule", () => {
	it("uses the pure retry policy for each scheduled failure", async () => {
		const schedule = createRetrySchedule(2, undefined, () => 0);
		const step = await Effect.runPromise(Schedule.toStep(schedule));
		const error = {
			status: 503,
			headers: new Headers(),
		};

		const first = await Effect.runPromise(step(0, error));
		const second = await Effect.runPromise(step(0, error));

		expect(first[1]).toEqual(Duration.millis(300));
		expect(second[1]).toEqual(Duration.millis(600));
	});

	it("stops after the configured number of retries", async () => {
		const schedule = createRetrySchedule(1, undefined, () => 0);
		const step = await Effect.runPromise(Schedule.toStep(schedule));
		const error = { status: 503, headers: new Headers() };

		await Effect.runPromise(step(0, error));
		const stopped = await Effect.runPromiseExit(step(0, error));

		expect(stopped).toMatchObject({ _tag: "Failure" });
	});

	it("advances retry waits deterministically with TestClock", async () => {
		let attempts = 0;
		const error = { status: 503, headers: new Headers() };
		const task = Effect.gen(function* () {
			attempts += 1;
			if (attempts === 1) yield* Effect.fail(error);
			return "ok";
		});
		const program = Effect.gen(function* () {
			const fiber = yield* Effect.retry(
				task,
				createRetrySchedule(1, undefined, () => 0),
			).pipe(Effect.forkChild);
			yield* TestClock.adjust("300 millis");
			return yield* Fiber.join(fiber);
		});

		await expect(
			Effect.runPromise(Effect.provide(program, TestClock.layer())),
		).resolves.toBe("ok");
		expect(attempts).toBe(2);
	});
});

